    go_modes = (self._drawing, self._pencolor, self._pensize, isinstance(self._fillpath, list))
    screen = self.screen
    undo_entry = ('go', self._position, end, go_modes, (self.currentLineItem, self.currentLine[:], screen._pointlist(self.currentLineItem), self.items[:]))
    if self.undobuffer:
        self.undobuffer.push(undo_entry)
    start = self._position
    if self._speed and screen._tracing == 1:
        diff = end - start
        diffsq = (diff[0] * screen.xscale) ** 2 + (diff[1] * screen.yscale) ** 2
        nhops = 1 + int(diffsq ** 0.5 / (3 * 1.1 ** self._speed * self._speed))
        delta = diff * (1.0 / nhops)
        for n in range(1, nhops):
            if n == 1:
                top = True
            else:
                top = False
            self._position = start + delta * n
            if self._drawing:
                screen._drawline(self.drawingLineItem, (start, self._position), self._pencolor, self._pensize, top)
            self._update()
        if self._drawing:
            screen._drawline(self.drawingLineItem, ((0, 0), (0, 0)), fill='', width=self._pensize)
    if self._drawing:
        self.currentLine.append(end)
    if isinstance(self._fillpath, list):
        self._fillpath.append(end)
    self._position = end
    if self._creatingPoly:
        self._poly.append(end)
    if len(self.currentLine) > 42:
        self._newLine()
    self._update()

def _undogoto(self, entry):
    """Reverse a _goto. Used for undo()
        """
    (old, new, go_modes, coodata) = entry
    (drawing, pc, ps, filling) = go_modes
    (cLI, cL, pl, items) = coodata
    screen = self.screen
    if abs(self._position - new) > 0.5:
        print('undogoto: HALLO-DA-STIMMT-WAS-NICHT!')
    self.currentLineItem = cLI
    self.currentLine = cL
    if pl == [(0, 0), (0, 0)]:
        usepc = ''
    else:
        usepc = pc
    screen._drawline(cLI, pl, fill=usepc, width=ps)
    todelete = [i for i in self.items if i not in items and screen._type(i) == 'line']
    for i in todelete:
        screen._delete(i)
        self.items.remove(i)
    start = old
    if self._speed and screen._tracing == 1:
        diff = old - new
        diffsq = (diff[0] * screen.xscale) ** 2 + (diff[1] * screen.yscale) ** 2
        nhops = 1 + int(diffsq ** 0.5 / (3 * 1.1 ** self._speed * self._speed))
        delta = diff * (1.0 / nhops)
        for n in range(1, nhops):
            if n == 1:
                top = True
            else:
                top = False
            self._position = new + delta * n
            if drawing:
                screen._drawline(self.drawingLineItem, (start, self._position), pc, ps, top)
            self._update()
        if drawing:
            screen._drawline(self.drawingLineItem, ((0, 0), (0, 0)), fill='', width=ps)
    self._position = old
    if self._creatingPoly:
        if len(self._poly) > 0:
            self._poly.pop()
        if self._poly == []:
            self._creatingPoly = False
            self._poly = None
    if filling:
        if self._fillpath == []:
            self._fillpath = None
            print('Unwahrscheinlich in _undogoto!')
        elif self._fillpath is not None:
            self._fillpath.pop()
    self._update()

def dot(self, size=None, *color):
    """Draw a dot with diameter size, using color.

        Optional arguments:
        size -- an integer >= 1 (if given)
        color -- a colorstring or a numeric color tuple

        Draw a circular dot with diameter size, using color.
        If size is not given, the maximum of pensize+4 and 2*pensize is used.

        Example (for a Turtle instance named turtle):
        >>> turtle.dot()
        >>> turtle.fd(50); turtle.dot(20, "blue"); turtle.fd(50)
        """
    if not color:
        if isinstance(size, (str, tuple)):
            color = self._colorstr(size)
            size = self._pensize + max(self._pensize, 4)
        else:
            color = self._pencolor
            if not size:
                size = self._pensize + max(self._pensize, 4)
    else:
        if size is None:
            size = self._pensize + max(self._pensize, 4)
        color = self._colorstr(color)
    if hasattr(self.screen, '_dot'):
        item = self.screen._dot(self._position, size, color)
        self.items.append(item)
        if self.undobuffer:
            self.undobuffer.push(('dot', item))
    else:
        pen = self.pen()
        if self.undobuffer:
            self.undobuffer.push(['seq'])
            self.undobuffer.cumulate = True
        try:
            if self.resizemode() == 'auto':
                self.ht()
            self.pendown()
            self.pensize(size)
            self.pencolor(color)
            self.forward(0)
        finally:
            self.pen(pen)
        if self.undobuffer:
            self.undobuffer.cumulate = False

def get_poly(self):
    """Return the lastly recorded polygon.

        No argument.

        Example (for a Turtle instance named turtle):
        >>> p = turtle.get_poly()
        >>> turtle.register_shape("myFavouriteShape", p)
        """
    if self._poly is not None:
        return tuple(self._poly)

def _delay(self, delay=None):
    """Set delay value which determines speed of turtle animation.
        """
    return self.screen.delay(delay)

def _undo(self, action, data):
    """Does the main part of the work for undo()
        """
    if self.undobuffer is None:
        return
    if action == 'rot':
        (angle, degPAU) = data
        self._rotate(-angle * degPAU / self._degreesPerAU)
        dummy = self.undobuffer.pop()
    elif action == 'stamp':
        stitem = data[0]
        self.clearstamp(stitem)
    elif action == 'go':
        self._undogoto(data)
    elif action in ['wri', 'dot']:
        item = data[0]
        self.screen._delete(item)
        self.items.remove(item)
    elif action == 'dofill':
        item = data[0]
        self.screen._drawpoly(item, ((0, 0), (0, 0), (0, 0)), fill='', outline='')
    elif action == 'beginfill':
        item = data[0]
        self._fillitem = self._fillpath = None
        if item in self.items:
            self.screen._delete(item)
            self.items.remove(item)
    elif action == 'pen':
        TPen.pen(self, data[0])
        self.undobuffer.pop()

def exitGracefully(x, y):
    """Screen.bye() with two dummy-parameters"""
    self.bye()
